            union_cols = ','.join(['NULL'] * len(columns))
            payloads.append(f"' UNION SELECT {union_cols} FROM {table_name}--")

        return payloads[0] if payloads else "' OR '1'='1'--"

    @staticmethod
    def generate_blind_injection(db_type: str, condition: str) -> str:
        """Generate blind SQL injection payload"""
