        self.use_ai = use_ai
        self.ai_gen = None

        if use_ai:
            AIProviderConfig.setup_from_config()
            self.ai_gen = AIExploitGenerator(provider=ai_provider)

    def generate_exploit_payload(self, 
                                payload_type: PayloadType,
                                target_info: Dict[str, Any]) -> Dict[str, Any]:
        """Generate complete exploit payload"""

        result = {
            'type': payload_type.value,
            'target': target_info,
            'payload': None,
            'explanation': None,
            'ai_generated': False
        }

        # Try AI generation first if enabled
        if self.use_ai and self.ai_gen:
            prompt = self._build_ai_prompt(payload_type, target_info)
            ai_code = self.ai_gen.generate_exploit(prompt)

            if ai_code:
                result['payload'] = ai_code
                result['ai_generated'] = True
                result['explanation'] = f"Generated by {self.ai_gen.provider} AI"
                return result

        # Fallback to template-based generation
        if payload_type == PayloadType.BUFFER_OVERFLOW:
            result['payload'] = self._generate_buffer_overflow(target_info)

        elif payload_type == PayloadType.SQL_INJECTION:
            result['payload'] = self._generate_sql_injection(target_info)

        elif payload_type == PayloadType.COMMAND_INJECTION:
            result['payload'] = self._generate_command_injection(target_info)

        elif payload_type == PayloadType.XSS:
            result['payload'] = self._generate_xss(target_info)

        elif payload_type == PayloadType.PATH_TRAVERSAL:
            result['payload'] = self._generate_path_traversal(target_info)

        return result

