class AIExploitGenerator:
    """AI-powered exploit code generation"""

    def __init__(self, provider: str = None, api_key: str = None):
        """
        Initialize AI exploit generator

        Args:
            provider: AI provider ('openai', 'mistral', 'ollama', 'azure')
            api_key: API key for the provider (auto-loaded from env if not provided)
        """
        self.provider = provider or self._detect_provider()
        self.api_key = api_key or os.environ.get(
            AIProviderConfig.PROVIDERS.get(self.provider, {}).get('key_env', '')
        )
        self.client = self._init_client()

    def _detect_provider(self) -> str:
        """Auto-detect best available AI provider"""
        available = AIProviderConfig.get_available_providers()

        # Priority order
        priority = ['openai', 'mistral', 'azure', 'ollama']
        for provider in priority:
            if provider in available:
                return provider

        return 'ollama'  # Fallback to local Ollama

    def _init_client(self):
        """Initialize AI client based on provider"""
        if self.provider == 'openai':
            from openai import OpenAI
            return OpenAI(api_key=self.api_key)

        elif self.provider == 'mistral':
            from mistralai import Mistral
            return Mistral(api_key=self.api_key)

        elif self.provider == 'azure':
            from openai import AzureOpenAI
            return AzureOpenAI(
                api_key=self.api_key,
                api_version="2024-02-15-preview",
                azure_endpoint=os.environ.get('AZURE_OPENAI_ENDPOINT')
            )

        elif self.provider == 'ollama':
            import ollama
            return ollama

        return None

    def generate_exploit(self, prompt: str, max_tokens: int = 2000) -> str:
        """Generate exploit code using AI"""
        try:
            if self.provider == 'openai':
                response = self.client.chat.completions.create(
                    model="gpt-4",
                    messages=[{"role": "user", "content": prompt}],
                    max_tokens=max_tokens,
                    temperature=0.7
                )
                return response.choices[0].message.content

            elif self.provider == 'mistral':
                response = self.client.chat.complete(
                    model="mistral-large",
                    messages=[{"role": "user", "content": prompt}],
                    max_tokens=max_tokens
                )
                return response.choices[0].message.content

            elif self.provider == 'azure':
                response = self.client.chat.completions.create(
                    deployment_id="gpt-4",
                    messages=[{"role": "user", "content": prompt}],
                    max_tokens=max_tokens
                )
                return response.choices[0].message.content

            elif self.provider == 'ollama':
                response = self.client.generate(
                    model="mistral",
                    prompt=prompt,
                    stream=False
                )
                return response['response']

        except Exception as e:
            print(f"AI generation failed ({self.provider}): {e}")
            return None


