        payload = b"A" * offset

        # Add ROP gadget markers
        if target_arch == 'x64':
            payload += b"\x90" * 8  # NOP sled for alignment
            payload += struct.pack('<Q', 0x4141414141414141)  # ROP target
        else:  # x86
            payload += b"\x90" * 4
            payload += struct.pack('<I', 0x41414141)

